package org.rabochaya.maptests;
import android.app.*;import java.util.*;import org.w3c.dom.Element;
/** Baseline probe only. Synthetic projects; Activity destruction is mandatory. */
final class ManagerConfirmationChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;
 ManagerConfirmationChecks(MapAndroidChecks m){this.m=m;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);}
 String positive(String kind){return kind.equals("delete")?"Удалить":kind.equals("show")?"Показать":kind.equals("hide")?"Скрыть":"Вставить";}
 long insert(Object store,String kind)throws Exception{String xml=ManagerRotationChecks.XML;if(kind.equals("show"))xml=xml.replace("<name>QA_ROTATE_POINT</name>","<name>QA_ROTATE_POINT</name><visibility>0</visibility>");Object doc=r.parse(xml.getBytes("UTF-8"));for(String id:new String[]{"point","other","nested"})m.staticCall("MediaLinks","add",new Class[]{m.codec,Element.class,String.class,String.class,byte[].class},doc,m.element(doc,id),id+".jpg","image/jpeg",new byte[]{2,5,8});return (Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_CONFIRM_"+kind);}
 void open(long id,String kind)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("QA_ROTATE_POINT");m.click("QA_ROTATE_OTHER");if(kind.startsWith("paste")){m.managerAction(kind.equals("pastecut")?"Вырезать":"Копировать");m.geometryReady();m.openManagerFolder("QA_ROTATE_FOLDER");m.managerAction("Вставить в эту папку");m.geometryReady();}else{m.setListingForm("QA_ROTATE_POINT",0,0,0,false,false,0);m.managerAction(kind.equals("delete")?"Удалить выбранное":kind.equals("show")?"Показать выбранные":"Скрыть выбранные");}}
 Map<String,?> prefs(){return new HashMap<>(m.getTargetContext().getSharedPreferences("object-manager-view",0).getAll());}
 String clip(Object store)throws Exception{Object c=m.objectClip(store);return c==null?"empty":m.clipStamp(c);}
 boolean shown(String kind){final boolean[] shown={false};m.runOnMainSync(()->shown[0]=v.button(m.activeDialogRoot(),positive(kind))!=null);return shown[0];}
 void run()throws Exception{m.installTileFixture();int network=m.requests.get();Object store=m.storeClass.getConstructor(android.content.Context.class).newInstance(m.getTargetContext());boolean all=true;try{for(String kind:new String[]{"delete","show","hide","pastecopy","pastecut"}){long id=insert(store,kind);try{open(id,kind);m.check(shown(kind),"baseline confirmation open: "+kind);v.controlReachable(positive(kind));v.controlReachable("Отмена");Object doc=r.load(store,id);byte[] before=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Map<String,?> settings=prefs();String stamp=clip(store);v.snapshot("confirm-"+kind+"-before",false);Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"actual confirmation Activity destroyed: "+kind);boolean restored=shown(kind);all&=restored;v.snapshot("confirm-"+kind+"-after",false);m.check(Arrays.equals(before,r.xml(r.load(store,id)))&&settings.equals(prefs())&&stamp.equals(clip(store)),"baseline rotation never applies XML/preferences/clipboard: "+kind);r.sameAssets(r.load(store,id),assets);v.emit("CONFIRM_BASELINE kind="+kind+" restored="+restored+" project="+id+" unchanged=true");}finally{v.finish();m.staticCall("ObjectClipboardWrites","clear",new Class[]{m.storeClass},store);m.call(store,"remove",new Class[]{long.class},id);}}m.check(m.requests.get()==network,"confirmation probe makes no tile requests");m.check(all,"all pending confirmations survive real Activity recreation");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
